    {
      "action": "update_status",
      "params": {
        "status": "promised"
      },
      "why": "El cliente ha confirmado que la disputa está resuelta y que abonará la diferencia pendiente."
    },
    {
      "action": "add_note",
      "params": {
        "note": "Cliente confirmó resolución de la disputa y solicita cambiar el estado a 'cancelled'. Se actualiza a 'promised' y se espera el pago de la diferencia."
