      "why": "Registrar internamente la información de la resolución y la solicitud del cliente."
    },
    {
      "action": "send_reminder",
      "params": {
        "reminder_text": "Estimado/a,\n\nConfirmamos que hemos recibido su mensaje y que la disputa sobre la factura F-2026-058 ha quedado resuelta. Procederemos a actualizar el estado de la factura y quedamos a la espera del abono de la diferencia acordada.\n\nMuchas gracias por su colaboración.\n\nSaludos cordiales,\n[Su Nombre]\n[Nombre de la empresa]",
        "reminder_channel": "email"
      },
      "why": "Enviar al cliente la confirmación del cambio de estado y del próximo abono."
    }
  ]
